use serde_json::{Value, from_str};
use std::cmp;

pub fn solve(input: Value) -> Value {
    let jobs: Vec<Vec<i64>> = input.as_array().unwrap().iter().map(|v| v.as_array().unwrap().to_vec()).collect();

    let mut finish_times = vec![0; jobs.len()];

    for i in 0..jobs.len() {
        let (arrival, duration) = (jobs[i][0], jobs[i][1]);
        finish_times[i] = cmp::max(arrival, finish_times[i - 1] + if i > 0 { jobs[i - 1][1] } else { 0 }) + duration;
    }

    Value::Array(finish_times.into_iter().map(Value::from).collect())
}
